public class InnerPaymentConnectorCredentialsProviderConfigurationFactory(Action<Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration> factoryAction = null) : SubResourceFactory<Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration>
{

    internal InnerPaymentConnectorPaymentCredentialProviderConfigurationFactory CoinbaseCDPFactory { get; set; }

    internal InnerPaymentConnectorPaymentCredentialProviderConfigurationFactory StripePrivyFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration Create()
    {
        var credentialsProviderConfigurationResult = CreateCredentialsProviderConfiguration();
        factoryAction?.Invoke(credentialsProviderConfigurationResult);

        return credentialsProviderConfigurationResult;
    }

    private Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration CreateCredentialsProviderConfiguration()
    {
        var credentialsProviderConfigurationResult = new Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration();

        return credentialsProviderConfigurationResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.PaymentConnectorTypes.CredentialsProviderConfiguration result)
    {
        base.CreateChildren(result);

        result.CoinbaseCDP ??= CoinbaseCDPFactory?.Build();
        result.StripePrivy ??= StripePrivyFactory?.Build();
    }

} // End Of Class

